edges = [(1, 7), (0, 7), (0, 1), (0, 2), (0, 3), (1, 2), (1, 4), (2, 3), (3, 5), (4, 5), (4, 6), (5, 6), (6, 7)]

# Check all constraints
print(f"Number of edges: {len(edges)}")

deg = [0]*8
for u,v in edges:
    deg[u] += 1
    deg[v] += 1
print(f"Degrees: {deg}")
print(f"Min degree: {min(deg)}")
print(f"Max degree: {max(deg)}")

# Check chromatic number
from collections import defaultdict
adj = defaultdict(set)
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

# Try 2-coloring (bipartite check)
colors = [-1]*8
def bfs_2color(start):
    from collections import deque
    q = deque([start])
    colors[start] = 0
    while q:
        v = q.popleft()
        for nb in adj[v]:
            if colors[nb] == -1:
                colors[nb] = 1 - colors[v]
                q.append(nb)
            elif colors[nb] == colors[v]:
                return False
    return True

is_bipartite = True
for v in range(8):
    if colors[v] == -1:
        if not bfs_2color(v):
            is_bipartite = False
            break
print(f"Is bipartite (2-colorable): {is_bipartite}")

# Try 3-coloring
colors3 = [-1]*8
def can_color(v, c):
    for nb in adj[v]:
        if colors3[nb] == c:
            return False
    return True

def backtrack(v):
    if v == 8:
        return True
    for c in range(3):
        if can_color(v, c):
            colors3[v] = c
            if backtrack(v+1):
                return True
            colors3[v] = -1
    return False

if backtrack(0):
    print(f"3-colorable: Yes, coloring: {colors3}")
else:
    print("3-colorable: No")

# Check fixed edges
print(f"Contains (1,7): {(1,7) in edges}")
print(f"Contains (0,7): {(0,7) in edges}")

# Check if chromatic number >= 2 (has at least one edge)
print(f"Has edges: {len(edges) > 0}")
